<?php
/**
 * Healthy Solutions (HSCF) theme.
 *
 * The site is generated by the project in GitHub (paco3463/hscfdoral, build/build.py --wp) and imported
 * into WordPress by inc/sync.php. This file keeps WordPress out of the way of that output: it registers the
 * English post type (/en/yyyy/mm/slug/), serves robots.txt, sitemap.xml, llms.txt and the feeds, handles the
 * old-URL redirects, and removes WordPress head clutter so the generated SEO tags are the only ones.
 */
if ( ! defined( 'ABSPATH' ) ) exit;

define( 'HSCF_THEME_VERSION', '1.0.0' );
require_once __DIR__ . '/inc/render.php';
require_once __DIR__ . '/inc/sync.php';
require_once __DIR__ . '/inc/contact.php';

/* ---------- English posts: their own type, at /en/<yyyy>/<mm>/<slug>/ ---------- */
add_action( 'init', function () {
	register_post_type( 'en_post', array(
		'labels'       => array( 'name' => 'English posts', 'singular_name' => 'English post', 'add_new_item' => 'Add English post', 'edit_item' => 'Edit English post', 'menu_name' => 'Posts (English)' ),
		'public'       => true,
		'show_in_rest' => true,
		'has_archive'  => false,
		'rewrite'      => false,
		'menu_position' => 6,
		'menu_icon'    => 'dashicons-translation',
		'supports'     => array( 'title', 'editor', 'excerpt', 'revisions', 'custom-fields' ),
	) );
	add_rewrite_rule( '^en/([0-9]{4})/([0-9]{2})/([^/]+)/?$', 'index.php?post_type=en_post&name=$matches[3]', 'top' );
	foreach ( array( '_hscf_path', '_hscf_lang', '_hscf_alt' ) as $key ) {
		register_post_meta( '', $key, array( 'type' => 'string', 'single' => true, 'show_in_rest' => true,
			'auth_callback' => function () { return current_user_can( 'edit_posts' ); } ) );
	}
}, 5 );

add_filter( 'post_type_link', function ( $link, $post ) {
	if ( $post->post_type !== 'en_post' || ! $post->post_name ) return $link;
	return home_url( '/en/' . get_post_time( 'Y', false, $post ) . '/' . get_post_time( 'm', false, $post ) . '/' . $post->post_name . '/' );
}, 10, 2 );

/* ---------- static files and redirects, before WordPress routes the request ---------- */
function hscf_request_path() {
	$path = rawurldecode( (string) parse_url( $_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH ) );
	$base = trim( (string) parse_url( home_url( '/' ), PHP_URL_PATH ), '/' );
	$path = ltrim( $path, '/' );
	if ( $base !== '' && strpos( $path, $base . '/' ) === 0 ) $path = substr( $path, strlen( $base ) + 1 );
	return $path;
}

add_action( 'init', function () {
	if ( is_admin() || ( defined( 'WP_CLI' ) && WP_CLI ) ) return;
	$path = hscf_request_path();
	if ( strpos( $path, 'wp-' ) === 0 || strpos( $path, 'xmlrpc' ) === 0 ) return;
	$index = get_option( 'hscf_static_index', array() );
	if ( is_array( $index ) && isset( $index[ $path ] ) ) {
		$types = array( 'txt' => 'text/plain', 'xml' => 'application/xml', 'webmanifest' => 'application/manifest+json' );
		$ext   = pathinfo( $path, PATHINFO_EXTENSION );
		$feed  = substr( $path, -8 ) === 'feed.xml';
		$type  = $feed ? 'application/rss+xml' : ( $types[ $ext ] ?? 'text/plain' );
		status_header( 200 );
		header( 'Content-Type: ' . $type . '; charset=utf-8' );
		header( 'Cache-Control: public, max-age=3600' );
		if ( $ext === 'txt' && $path !== 'robots.txt' || $feed ) header( 'X-Robots-Tag: noindex' );
		echo hscf_t( get_option( $index[ $path ], '' ) );
		exit;
	}
	foreach ( (array) get_option( 'hscf_redirects', array() ) as $r ) {
		if ( is_array( $r ) && count( $r ) === 2 && @preg_match( '#^' . $r[0] . '/?$#i', $path ) ) {
			wp_redirect( home_url( '/' . ltrim( $r[1], '/' ) ), 301, 'HSCF' );
			exit;
		}
	}
}, 1 );

/* ---------- keep WordPress's own output out of the generated pages ---------- */
add_action( 'after_setup_theme', function () {
	remove_action( 'wp_head', 'rel_canonical' );
	remove_action( 'wp_head', 'wp_robots', 1 );
	remove_action( 'wp_head', 'wp_generator' );
	remove_action( 'wp_head', 'wp_shortlink_wp_head' );
	remove_action( 'wp_head', 'rsd_link' );
	remove_action( 'wp_head', 'wlwmanifest_link' );
	remove_action( 'wp_head', 'feed_links', 2 );
	remove_action( 'wp_head', 'feed_links_extra', 3 );
	remove_action( 'wp_head', 'rest_output_link_wp_head' );
	remove_action( 'wp_head', 'wp_oembed_add_discovery_links' );
	remove_action( 'wp_head', 'print_emoji_detection_script', 7 );
	remove_action( 'wp_print_styles', 'print_emoji_styles' );
	remove_action( 'wp_head', 'wp_site_icon', 99 );
	remove_action( 'template_redirect', 'rest_output_link_header', 11 );
	remove_action( 'template_redirect', 'wp_shortlink_header', 11 );
	remove_action( 'wp_enqueue_scripts', 'wp_enqueue_global_styles' );
	remove_action( 'wp_footer', 'wp_enqueue_global_styles', 1 );
	remove_action( 'wp_body_open', 'wp_global_styles_render_svg_filters' );
	add_theme_support( 'html5', array( 'script', 'style' ) );
} );
add_action( 'wp_enqueue_scripts', function () {
	foreach ( array( 'wp-block-library', 'wp-block-library-theme', 'classic-theme-styles', 'global-styles', 'core-block-supports' ) as $h ) {
		wp_dequeue_style( $h );
	}
}, 100 );
add_filter( 'wp_img_tag_add_auto_sizes', '__return_false' );
add_filter( 'wp_sitemaps_enabled', '__return_false' );
add_filter( 'xmlrpc_enabled', '__return_false' );
add_filter( 'comments_open', '__return_false', 20 );
add_filter( 'pings_open', '__return_false', 20 );
add_filter( 'show_recent_comments_widget_style', '__return_false' );
add_filter( 'redirect_canonical', function ( $url ) {
	// Static files are answered on init; never let WordPress "guess" a page for a missing address.
	return is_404() ? false : $url;
} );
add_filter( 'do_redirect_guess_404_permalink', '__return_false' );

// Author archives, attachment pages and search are not part of this site.
add_action( 'template_redirect', function () {
	if ( is_author() || is_attachment() || is_search() || is_date() || is_category() || is_tag() || ( is_home() && ! is_front_page() ) ) {
		global $wp_query;
		$wp_query->set_404();
		status_header( 404 );
		nocache_headers();
	}
}, 1 );

/* ---------- admin: say plainly how this site is managed ---------- */
add_action( 'admin_notices', function () {
	$screen = function_exists( 'get_current_screen' ) ? get_current_screen() : null;
	if ( ! $screen || $screen->base !== 'post' ) return;
	global $post;
	if ( ! $post || ! hscf_is_item( $post->ID ) ) return;
	echo '<div class="notice notice-info"><p><strong>Healthy Solutions:</strong> this page comes from the site project on GitHub. '
		. 'You can edit its text here; the next automatic update will keep your edit and report it instead of overwriting it. '
		. 'Its Spanish/English twin is <code>' . esc_html( get_post_meta( $post->ID, '_hscf_alt', true ) ?: '/' ) . '</code>.</p></div>';
} );
